// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint128).max);
        vm.assume(actor != address(c));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 balanceBefore = c.getBalance(actor);
        uint256 ethBefore = actor.balance;

        vm.prank(actor);
        c.withdrawBalance();

        uint256 balanceAfter = c.getBalance(actor);
        uint256 ethAfter = actor.balance;

        assertTrue(balanceAfter == 0 && ethAfter == ethBefore + balanceBefore);
    }
}
